import{_ as l,a0 as p,w as o,s as d,I as s,x as e,a1 as n,A as a,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 中从 PDF 创建视频 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中从 PDF 创建视频 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中从 PDF 创建视频 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中从 PDF 创建视频 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171004 How To Create A Video From PDF Files In Linux","title":"如何在 Linux 中从 PDF 创建视频","tag":"201801","desc":""},"relativePath":"201801/20171004 How To Create A Video From PDF Files In Linux.md","filePath":"[post].md"}'),g={name:"201801/20171004 How To Create A Video From PDF Files In Linux.md"};function u(h,i,k,f,c,m){const t=p("Link");return o(),d("div",null,[i[17]||(i[17]=s("h1",{id:"如何在-linux-中从-pdf-创建视频",tabindex:"-1"},[e("如何在 Linux 中从 PDF 创建视频 "),s("a",{class:"header-anchor",href:"#如何在-linux-中从-pdf-创建视频","aria-label":"Permalink to “如何在 Linux 中从 PDF 创建视频”"},"​")],-1)),i[18]||(i[18]=s("p",null,[s("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/Video-1-720x340.jpg",alt:""})],-1)),s("p",null,[i[1]||(i[1]=e("我在我的平板电脑中收集了大量的 PDF 文件，其中主要是 Linux 教程。有时候我懒得在平板电脑上看。我认为如果我能够从 PDF 创建视频，并在大屏幕设备（如电视机或计算机）中观看会更好。虽然我对 ",-1)),n(t,{href:"https://www.ostechnix.com/20-ffmpeg-commands-beginners/"},{default:a(()=>[...i[0]||(i[0]=[e("FFMpeg",-1)])]),_:1}),i[2]||(i[2]=e(" 有一些经验，但我不知道如何使用它来创建视频。经过一番 Google 搜索，我想出了一个很好的解决方案。对于那些想从一组 PDF 文件制作视频文件的人，请继续阅读。这并不困难。",-1))]),i[19]||(i[19]=s("h3",{id:"在-linux-中从-pdf-创建视频",tabindex:"-1"},[e("在 Linux 中从 PDF 创建视频 "),s("a",{class:"header-anchor",href:"#在-linux-中从-pdf-创建视频","aria-label":"Permalink to “在 Linux 中从 PDF 创建视频”"},"​")],-1)),i[20]||(i[20]=s("p",null,"为此，你需要在系统中安装 “FFMpeg” 和 “ImageMagick”。",-1)),i[21]||(i[21]=s("p",null,"要安装 FFMpeg，请参考以下链接。",-1)),s("ul",null,[s("li",null,[n(t,{href:"https://www.ostechnix.com/install-ffmpeg-linux/"},{default:a(()=>[...i[3]||(i[3]=[e("在 Linux 上安装 FFMpeg",-1)])]),_:1})])]),i[22]||(i[22]=r('<p>Imagemagick 可在大多数 Linux 发行版的官方仓库中找到。</p><p>在 Arch Linux 以及 Antergos、Manjaro Linux 等衍生产品上，运行以下命令进行安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S imagemagick</span></span></code></pre></div><p>Debian、Ubuntu、Linux Mint：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install imagemagick</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install imagemagick</span></span></code></pre></div><p>RHEL、CentOS、Scientific Linux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install imagemagick</span></span></code></pre></div><p>SUSE、 openSUSE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zypper install imagemagick</span></span></code></pre></div><p>在安装 ffmpeg 和 imagemagick 之后，将你的 PDF 文件转换成图像格式，如 PNG 或 JPG，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>convert -density 400 input.pdf picture.png</span></span></code></pre></div><p>这里，<code>-density 400</code> 指定输出图像的水平分辨率。</p><p>上面的命令会将指定 PDF 的所有页面转换为 PNG 格式。PDF 中的每个页面都将被转换成 PNG 文件，并保存在当前目录中，文件名为： <code>picture-1.png</code>、 <code>picture-2.png</code> 等。根据选择的 PDF 的页数，这将需要一些时间。</p><p>将 PDF 中的所有页面转换为 PNG 格式后，运行以下命令以从 PNG 创建视频文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ffmpeg -r 1/10 -i picture-%01d.png -c:v libx264 -r 30 -pix_fmt yuv420p video.mp4</span></span></code></pre></div><p>这里：</p><ul><li><code>-r 1/10</code> ：每张图像显示 10 秒。</li><li><code>-i picture-%01d.png</code> ：读取以 <code>picture-</code> 开头，接着是一位数字（<code>％01d</code>），最后以 <code>.png</code> 结尾的所有图片。如果图片名称带有 2 位数字（也就是 <code>picture-10.png</code>、<code>picture11.png</code> 等），在上面的命令中使用（<code>％02d</code>）。</li><li><code>-c:v libx264</code>：输出的视频编码器（即 h264）。</li><li><code>-r 30</code> ：输出视频的帧率</li><li><code>-pix_fmt yuv420p</code>：输出的视频分辨率</li><li><code>video.mp4</code>：以 .mp4 格式输出视频文件。</li></ul><p>好了，视频文件完成了！你可以在任何支持 .mp4 格式的设备上播放它。接下来，我需要找到一种方法来为我的视频插入一个很酷的音乐。我希望这也不难。</p><p>如果你想要更高的分辨率，你不必重新开始。只要将输出的视频文件转换为你选择的任何其他更高/更低的分辨率，比如说 720p，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ffmpeg -i video.mp4 -vf scale=-1:720 video_720p.mp4</span></span></code></pre></div><p>请注意，使用 ffmpeg 创建视频需要一台配置好的 PC。在转换视频时，ffmpeg 会消耗大量系统资源。我建议在高端系统中这样做。</p><p>就是这些了。希望你觉得这个有帮助。还会有更好的东西。敬请关注！</p><hr>',25)),s("p",null,[i[5]||(i[5]=e("via: ",-1)),n(t,{href:"https://www.ostechnix.com/create-video-pdf-files-linux/"},{default:a(()=>[...i[4]||(i[4]=[e("https://www.ostechnix.com/create-video-pdf-files-linux/",-1)])]),_:1})]),s("p",null,[i[9]||(i[9]=e("作者：",-1)),n(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...i[6]||(i[6]=[e("SK",-1)])]),_:1}),i[10]||(i[10]=e(" 译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:a(()=>[...i[7]||(i[7]=[e("geekpi",-1)])]),_:1}),i[11]||(i[11]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[8]||(i[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[14]||(i[14]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[12]||(i[12]=[e("LCTT",-1)])]),_:1}),i[15]||(i[15]=e(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...i[13]||(i[13]=[e("Linux中国",-1)])]),_:1}),i[16]||(i[16]=e(" 荣誉推出",-1))])])}const F=l(g,[["render",u]]);export{C as __pageData,F as default};
